  return {
    score,
    ampel,
    gruende: gruende.sort((a, b) => Math.abs(b.punkte) - Math.abs(a.punkte)),
    region,
    nutzbarHa,
    kwp,
    kwh,
    netzProKwp,
    pachtJahr: { min: pachtMin, max: pachtMax },
    pacht30: { min: pachtMin * faktor30, max: pachtMax * faktor30 },
