                      <li key={r.slug}>
                        <Link href={`${PFAD}/${r.slug}`} className="group flex items-center justify-between gap-3 rounded-xl px-2 py-2 text-[15px] text-ink-800 hover:bg-ov-50 hover:text-ov-800">
                          <span className="min-w-0">
