                          </span>
                          <ArrowRight aria-hidden="true" className="h-4 w-4 shrink-0 text-ov-600 opacity-60 transition-all group-hover:translate-x-0.5 group-hover:opacity-100" />
                        </Link>
                      </li>
                    ))}
                  </ul>
                </Reveal>
              );
            })}
