const [pfad, breite = "390", name = "unten"] = process.argv.slice(2);
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: +breite, height: 1600 } });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
const r = await p.goto("http://localhost:3100" + pfad, { waitUntil: "load", timeout: 540000 });
await p.evaluate(() => document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible")));
try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
const start = await p.evaluate(() => { const el = document.getElementById("anfrage"); return el ? el.getBoundingClientRect().top + window.scrollY : 0; });
const hoehe = await p.evaluate(() => document.body.scrollHeight);
let i = 0;
for (let y = start; y < hoehe; y += 1600) { await p.evaluate((y) => window.scrollTo(0, y), y); await p.waitForTimeout(500); await p.screenshot({ path: `shots/${name}_${breite}_u${i++}.png` }); }
console.log(r.status(), i, "Bilder", fehler.join(" | "));
await b.close();
EOF
